#include <stdlib.h>
#include <string.h>
#include <omp.h>

#if defined(__AVX512F__)
#define MR 12
#define NR 32
#define VW 16
typedef float vf __attribute__((vector_size(64)));
#else
#define MR 6
#define NR 16
#define VW 8
typedef float vf __attribute__((vector_size(32)));
#endif

#define NV (NR / VW)
#define KC 256
#define MC (MR * 8)
#define NC (NR * 4)

static inline vf loadu(const float *p) { vf v; memcpy(&v, p, sizeof v); return v; }
static inline void storeu(float *p, vf v) { memcpy(p, &v, sizeof v); }

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int mr, int nr, int first)
{
    vf acc[MR][NV];
    #pragma GCC unroll 16
    for (int r = 0; r < MR; r++)
        #pragma GCC unroll 4
        for (int v = 0; v < NV; v++)
            acc[r][v] = (vf){0};

    #pragma GCC unroll 16
    for (int r = 0; r < MR; r++)
        if (r < mr) __builtin_prefetch(c + (size_t)r * ldc, 1, 3);

    for (int k = 0; k < kc; k++) {
        vf bv[NV];
        #pragma GCC unroll 4
        for (int v = 0; v < NV; v++)
            bv[v] = loadu(b + (size_t)NR * k + VW * v);
        const float *ap = a + (size_t)MR * k;
        #pragma GCC unroll 16
        for (int r = 0; r < MR; r++) {
            float ar = ap[r];
            #pragma GCC unroll 4
            for (int v = 0; v < NV; v++)
                acc[r][v] += bv[v] * ar;
        }
    }

    if (mr == MR && nr == NR) {
        #pragma GCC unroll 16
        for (int r = 0; r < MR; r++) {
            float *cr = c + (size_t)r * ldc;
            #pragma GCC unroll 4
            for (int v = 0; v < NV; v++) {
                if (first)
                    storeu(cr + VW * v, acc[r][v]);
                else
                    storeu(cr + VW * v, loadu(cr + VW * v) + acc[r][v]);
            }
        }
    } else {
        float tmp[MR][NR];
        for (int r = 0; r < MR; r++)
            for (int v = 0; v < NV; v++)
                memcpy(&tmp[r][VW * v], &acc[r][v], sizeof(vf));
        for (int r = 0; r < mr; r++) {
            float *cr = c + (size_t)r * ldc;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = tmp[r][j];
            else
                for (int j = 0; j < nr; j++) cr[j] += tmp[r][j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int nstrips = (n + MR - 1) / MR;
    int npanels = (n + NR - 1) / NR;

    size_t asz = ((size_t)nstrips * MR * n * sizeof(float) + 63) & ~(size_t)63;
    size_t bsz = ((size_t)npanels * NR * n * sizeof(float) + 63) & ~(size_t)63;
    float *Ap = (float *)aligned_alloc(64, asz);
    float *Bp = (float *)aligned_alloc(64, bsz);

    int mblocks = (n + MC - 1) / MC;
    int nblocks = (n + NC - 1) / NC;
    int ntasks = mblocks * nblocks;

    #pragma omp parallel
    {
        /* Pack all of B: panel p holds columns [p*NR, p*NR+NR) for every k. */
        #pragma omp for schedule(static) nowait
        for (int p = 0; p < npanels; p++) {
            float *dst = Bp + (size_t)p * n * NR;
            int j0 = p * NR;
            int w = n - j0 < NR ? n - j0 : NR;
            for (int k = 0; k < n; k++) {
                const float *src = B + (size_t)k * n + j0;
                float *d = dst + (size_t)k * NR;
                if (w == NR) {
                    memcpy(d, src, NR * sizeof(float));
                } else {
                    int j = 0;
                    for (; j < w; j++) d[j] = src[j];
                    for (; j < NR; j++) d[j] = 0.0f;
                }
            }
        }

        /* Pack all of A: strip s holds rows [s*MR, s*MR+MR) interleaved by k. */
        #pragma omp for schedule(static)
        for (int s = 0; s < nstrips; s++) {
            float *dst = Ap + (size_t)s * n * MR;
            int i0 = s * MR;
            int h = n - i0 < MR ? n - i0 : MR;
            for (int r = 0; r < MR; r++) {
                if (r < h) {
                    const float *src = A + (size_t)(i0 + r) * n;
                    for (int k = 0; k < n; k++) dst[(size_t)k * MR + r] = src[k];
                } else {
                    for (int k = 0; k < n; k++) dst[(size_t)k * MR + r] = 0.0f;
                }
            }
        }

        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntasks; t++) {
            int ib = t / nblocks, jb = t % nblocks;
            int i0 = ib * MC;
            int iend = i0 + MC < n ? i0 + MC : n;
            int jstart = jb * NC;
            int jend = jstart + NC < n ? jstart + NC : n;

            for (int k0 = 0; k0 < n; k0 += KC) {
                int kc = n - k0 < KC ? n - k0 : KC;
                int first = (k0 == 0);
                for (int j = jstart; j < jend; j += NR) {
                    const float *bp = Bp + (size_t)(j / NR) * n * NR + (size_t)k0 * NR;
                    int nr = n - j < NR ? n - j : NR;
                    for (int i = i0; i < iend; i += MR) {
                        const float *ap = Ap + (size_t)(i / MR) * n * MR + (size_t)k0 * MR;
                        int mr = n - i < MR ? n - i : MR;
                        kernel(kc, ap, bp, C + (size_t)i * n + j, n, mr, nr, first);
                    }
                }
            }
        }
    }

    free(Ap);
    free(Bp);
}
